    public function run()
    {
        $h5pIVLibParams = ['name' => "H5P.InteractiveVideo", "major_version" => 1, "minor_version" => 28];
        $h5pIVLib = DB::table('h5p_libraries')->where($h5pIVLibParams)->first();

        if (empty($h5pIVLib)) {
            $h5pIVLibId = DB::table('h5p_libraries')->insertGetId([
                'name' => 'H5P.InteractiveVideo',
                'title' => 'Interactive Video',
                'major_version' => 1,
                'minor_version' => 28,
                'patch_version' => 35,
                'embed_types' => 'iframe',
                'runnable' => 1,
                'restricted' => 0,
                'fullscreen' => 1,
                'preloaded_js' => 'dist/h5p-interactive-video.js',
                'preloaded_css' => 'dist/h5p-interactive-video.css',
                'drop_library_css' => '',
                'semantics' => $this->getSemantics(),
                'tutorial_url' => ' ',
                'has_icon' => 1
            ]);

            $this->insertDependentLibraries($h5pIVLibId);
            $this->insertLibrariesLanguages($h5pIVLibId);

            $organizations = DB::table('organizations')->pluck('id');
            $currentDate = now();

            foreach ($organizations as $organizationId) {
                $activityTypes = DB::table('activity_types')->whereOrganizationId($organizationId)->pluck('id', 'title');
                if (!isset($activityTypes['Video'])) {
                    continue;
                }
                $params = ['title' => 'Interactive Video', 'organization_id' => $organizationId];
                DB::table('activity_items')->updateOrInsert($params, [
                    'title' => 'Interactive Video',
                    'image' => '',
                    'description' => 'Add interactivity to your video with questions and other tasks',
                    'activity_type_id' => $activityTypes['Video'],
                    'h5pLib' => 'H5P.InteractiveVideo 1.28',
                    'demo_activity_id' => '0',
                    'demo_video_id' => '',
                    'type' => 'h5p',
                    'created_at' => $currentDate,
                    'deleted_at' => null,
                    'organization_id' => $organizationId,
                ]);
            }
        }
    }

