            'translation' => json_encode(json_decode('{"semantics":[{"label":"Interaktiv video-editor","fields":[{"label":"Upload/indlejr video","fields":[{"label":"Tilføj en video","description":"Klik nedenfor for at tilføje en video, som du ønsker at bruge i din interaktive video. Du kan tilføje et videolink eller uploade videofiler. Det er muligt at tilføje flere versioner af videoen i forskellig kvalitet. For at sikre maksimal understøttelse i browsere tilføj mindst en version i webm og mp4-formater."},{"label":"Start screen options (unsupported for YouTube videos)","fields":[{"label":"Titlen på denne interaktive video","default":"Interaktiv video","description":"Brugt i resuméer, statistikker osv."},{"label":"Skjul titel på video-startskærm"},{"label":"Kort beskrivelse (valgfri)","description":"Valgfri. Vis en kort beskrivelse når en video uploades. Virker ikke med YouTube-videoer."},{"label":"Forsidebillede","description":"Billedet vises før brugeren starter videoen. Virker ikke med YouTube-videoer."}]},{"label":"Text tracks (unsupported for YouTube videos)","fields":[{"label":"Tilgængelige tekstspor","entity":"Track","field":{"label":"Spor","fields":[{"label":"Sporetiket","description":"Anvendes hvis du tilbyder flere spor som brugeren kan vælge i mellem. For eksempel kunne \'Spanske undertekster\' være etiketten for et spansk undertekstspor.","default":"Undertekster"},{"label":"Typer af tekstspor","options":[{"label":"Undertekster"},{"label":"Undertitel"},{"label":"Beskrivelser"}]},{"label":"Kildesprog, skal være defineret for undertekster","description":"Skal være en gyldig BCP 47 sprogtag. Hvis \"Undertekster\" er det valgte tekstspor skal kildesproget til sporet defineres."},{"label":"Sporkilde (WebVTT-fil)"}]}},{"label":"Default text track","description":"If left empty or not matching any of the text tracks the first text track will be used as the default."}]}]},{"label":"Tilføj interaktioner","fields":[{"field":{"fields":[{"label":"Visningstid"},{"label