            'translation' => json_encode(json_decode('{"semantics":[{"label":"Editor for interaktiv video","fields":[{"label":"Last opp video","fields":[{"label":"Legg til en video","description":"Velg videoen du vil bruke. Du kan legge til ei videolenke eller laste opp videofiler. Det er mulig å legge til flere videoversjoner med forskjellig oppløsning. For å sikre maksimal støtte i alle nettleserne bør du legge til i hvert fall en versjon i WebM- og en i MP4-format."},{"label":"Valgmuligheter for startbilde (støttes ikke for YouTube-videoer)","fields":[{"label":"Tittel på den interaktive videoen","default":"Interaktiv video","description":"Brukes i oppsummeringer, statistikker osv."},{"label":"Skjul tittel på startskjerm"},{"label":"Kort beskrivelse (valgfri)","description":"Viser en kort beskrivelse på startskjermen. Fungerer ikke for YouTube-videoer."},{"label":"Plakat (valgfri)","description":"Bilde som vises før videoen spilles av. Fungerer ikke for YouTube-videoer."}]},{"label":"Tekstspor (støttes ikke for YouTube-videoer)","fields":[{"label":"Tilgjengelige tekstspor","entity":"Tekstspor","field":{"label":"Spor","fields":[{"label":"Navn på tekstspor","description":"Brukes dersom det fins flere tekstspor og bruker må velge ett av dem. Eksempel: \"Nynorsk\" kan være navnet på et tekstspor med tekst på nynorsk.","default":"Teksting"},{"label":"Type tekstspor","options":[{"label":"Undertekster"},{"label":"Teksting for hørselshemmede"},{"label":"Beskrivelser for skjermleser"}]},{"label":"Kildespråk","description":"Må være en gyldig BCP 47-språktagg. Hvis \"Undertekster\" er valgt, må du definere språket i tekstsporet."},{"label":"Tekstfil (WebVTT-fil)"}]}},{"label":"Standard tekstspor","description":"Hvis dette feltet står tomt eller ikke samsvarer med et tilgjengelig tekstspor, blir det første tekstsporet brukt."}]}]},{"label":"Legg til interaktive elementer","fields":[{"field":{"fields":[{"label":"Visningstid"},{"label":"Sett videoen på pause"},{"label":"Vis som","description":"Velger du <b>Knapp</b> , må brukeren trykke på en knapp for å få vist innholdet. Velger du <b>Plakat</b>, blir innholdet vist automatisk.","options":[{"label":"Knapp"},{"label":"Plakat"}]},{"label":"Vis som knapp på små skjermer"},{"label":"Tittel","description":"Tekst ved siden av interaksjonsikonet."},{},{},{},{},{},{},{"label":"Tilpasning","fields":[{"label":"Handling dersom alle svar er riktige","fields":[{"label":"Gå til","description":"Legg inn tidskode i formatet M:SS"},{"label":"Tillat bruker å velge bort aktivitet og heller fortsette å se video"},{"label":"Melding"},{"label":"Navn på \"Gå til\"-knapp"}]},{"label":"Handling ved feil svar","fields":[{"label":"Gå til","description":"Legg inn tidskode i formatet M:SS"},{"label":"Tillat bruker å velge bort aktivitet og heller å fortsette å se video"},{"label":"Melding"},{"label":"Navn på \"Gå til\"-knapp"}]},{"label":"Krev rett svar på alt før bruker får gå videre","description":"Du får best funksjonalitet om du velger \"Deaktiver navigering framover i video\" sammen med denne innstillinga."}]},{"label":"Visuelle effekter","fields":[{"label":"Bakgrunnsfarge"},{"label":"Skygge","description":"Legger på en svak skygge rundt interaksjonsfeltet. Deaktiver om du vil ha helt gjennomsiktige interaksjonsfelt."}]},{"label":"Ved klikk gå til","fields":[{"label":"Type","options":[{"label":"Tidskode"},{"label":"Ei annen side (URL)"}]},{"label":"Gå til","description":"Tidspunktet i videoen som bruker blir sendt til når hen klikker på hotspoten. Legg inn i formatet M:SS."},{"label":"URL","fields":[{"label":"Protokoll","options":[{"label":"http://"},{"label":"https://"},{"label":"(sti på dette domenet)"},{"label":"annen"}]},{"label":"URL"}]},{"label":"Vis som klikkbar","description":"Hvis du velger dette, blir det lagt til ei kantlinje og et ikon som viser at det interaktive elementet er klikkbart."}]}]}},{},{}]},{"label":"Oppsummeringsoppgave","fields":[{},{"label":"Visningstidspunkt","description":"Antall se