            'translation' => json_encode(json_decode('{"semantics":[{"label":"ఇంటరాక్టివ్ వీడియో ఎడిటర్","fields":[{"label":"వీడియో అప్‌లోడ్ /ఎంబెడ్","fields":[{"label":"వీడియోని జోడించండి","description":"మీరు మీ ఇంటరాక్టివ్ వీడియోలో ఉపయోగించాలనుకుంటున్న వీడియోను జోడించడానికి దిగువ క్లిక్ చేయండి. మీరు వీడియో లింక్‌ను జోడించవచ్చు లేదా వీడియో ఫైల్‌లను అప్‌లోడ్ చేయవచ్చు. విభిన్న లక్షణాలతో వీడియో యొక్క అనేక వెర్షన్‌లను జోడించడం సాధ్యమవుతుంది. బ్రౌజర్‌లలో గరిష్ట మద్దతుని నిర్ధారించడానికి కనీసం webm మరియు mp4 ఫార్మాట్‌లలో సంస్కరణను జోడించండి."},{"label":"ప్రారంభ స్క్రీన్ ఎంపికలు (YouTube వీడియోలకు మద్దతు లేదు)","fields":[{"label":"ఈ ఇంటరాక్టివ్ వీడియో యొక్క శీర్షిక","default":"ఇంటరాక్టివ్ వీడియో","description":"సమ్మరీ , గణాంకాలలో వాడబడుతుంది."},{"label":"వీడియో ప్రారంభ స్క్రీన్‌లో శీర్షికను దాచి ఉంచండి"},{"label":"సంక్షిప్త వివరణ (ఆప్షనల్)","description":"ఆప్షనల్. వీడియో ప్రారంభ స్క్రీన్‌లో చిన్న వివరణ టెక్స్ట్ ను ప్రదర్శించండి. YouTube వీడియోలకు పని చేయదు."},{"label":"పోస్టర్ చిత్రం","description":"యూజరు వీడియోను ప్రారంభించే ముందు చిత్రం ప్రదర్శించబడుతుంది. YouTube వీడియోల కోసం పని చేయదు."}]},{"label":"టెక్స్ట్ ట్రాక్‌లు (YouTube వీడియోలకు మద్దతు లేదు)","fields":[{"label":"అందుబాటులో ఉన్న టెక్స్ట్ ట్రాక్‌లు","entity":"ట్రాక్ చేయండి","field":{"label":"ట్రాక్ చేయండి","fields":[{"label":"ట్రాక్ లేబుల్","description":"మీరు బహుళ ట్రాక్‌లను అందిస్తే ఉపయోగించబడుతుంది మరియు యూజరు ట్రాక్‌ని ఎంచుకోవలసి ఉంటుంది. ఉదాహరణకు \'స్పానిష్ ఉపశీర్షికలు\' అనేది స్పానిష్ సబ్‌టైటిల్ ట్రాక్ యొక్క లేబుల్ కావచ్చు.","default":"సబ్ టైటిల్స్"},{"label":"టెక్స్ట్ ట్రాక్ రకం","options":[{"label":"ఉపశీర్షికలు"},{"label":"శీర్షికలు"},{"label":"వివరణలు"}]},{"label":"ఉపశీర్షికల కోసం మూల భాష తప్పనిసరిగా నిర్వచించబడాలి","description":"తప్పనిసరిగా చెల్లుబాటు అయ్యే BCP 47 భాషా ట్యాగ్ అయి ఉండాలి. \'సబ్‌టైటిల్స్\' అనేది ఎంచుకున్న టెక్స్ట్ ట్రాక్ రకం అయితే, ట్రాక్ యొక్క మూల భాషను తప్పనిసరిగా నిర్వచించాలి."},{"label":"ట్రాక్ మూలం (WebVTT file)"}]}},{"label":"డిఫాల్ట్ టెక్స్ట్ ట్రాక్","description":"ఖాళీగా వదిలేస్